// The load suite signs shift commands exactly as the tablet does (P2.12a burst, tests/load/shift-change.js): this
// bundles @karry/crypto (RFC 8785, envelopes, ES256) into one ES module k6 can import. k6 has no TextEncoder, btoa or
// atob: tests/load/lib/k6-shims.js provides them. The bundle is committed (the nightly load job has no Node);
// `--check` fails when it is not what this package builds today (CI, like the API client's check:generated).
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const here = dirname(fileURLToPath(import.meta.url));
const target = resolve(here, "../../../../../tests/load/lib/crypto.gen.js");
const banner = "// GENERATED by src/frontend/packages/crypto/scripts/k6-bundle.mjs from @karry/crypto: do not edit.";

const result = await build({
  entryPoints: [resolve(here, "../src/index.ts")],
  bundle: true,
  format: "esm",
  platform: "neutral",
  target: "es2020",
  write: false,
  legalComments: "none",
  banner: { js: banner },
});
const text = result.outputFiles[0].text.replace(/\r\n/g, "\n");

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf8").replace(/\r\n/g, "\n");
  } catch {
    // missing: reported below
  }

  if (current !== text) {
    console.error(`${target} is not the bundle of @karry/crypto: run pnpm --filter @karry/crypto bundle:k6 and commit it.`);
    process.exit(1);
  }

  console.log("k6 bundle of @karry/crypto is up to date.");
} else {
  writeFileSync(target, text);
  console.log(`wrote ${target}`);
}
